'use strict';

// Full-site presentation and demo state. No authentication or publishing network calls.
const routeTitles={content:'内容库',editor:'编辑文章',publish:'发布确认',distribution:'文章分发详情',deliveries:'发布与任务',analytics:'数据分析',connections:'连接与渠道',settings:'站点与工作区',members:'成员与权限',guide:'开始使用',login:'欢迎回来',onboarding:'开始创作',blog:'Journal',story:'阅读文章'};
const site={signedIn:true,returnTo:'content',loginError:'',onboardingStep:1,chosenWorkspace:'org',provisioning:{org:false,personal:false},deliveryFilter:'all',deliveryPlatform:'all',deliveryQuery:'',analyticsPeriod:'30',analyticsArticle:'all',analyticsLang:'all',analyticsSource:'ghost',publicOwner:'org',publicLang:'en',publicCategory:'all',publicQuery:'',storyId:'identity',settingsTab:'general',channel:null,settings:{org:{name:'ChronoAI',description:'Ideas on identity, agents, and the future of connected work.',language:'en'},personal:{name:'Jing’s Notes',description:'Notes on building useful things, one idea at a time.',language:'en'}},members:[{name:'Jing Chen',initials:'JC',email:'jing@chronoai.example',role:'publisher',self:true},{name:'Alex Wu',initials:'AW',email:'alex@chronoai.example',role:'publisher'},{name:'Sarah Lin',initials:'SL',email:'sarah@chronoai.example',role:'member'},{name:'Evan Liu',initials:'EL',email:'evan@chronoai.example',role:'admin'}]};
const initialTask=distributionState();
initialTask.dev='approval_needed';
initialTask.medium='manual_action_needed';
initialTask.hashnode='unconfigured';
initialTask.hacker='manual_action_needed';
initialTask.hackerSnapshot={...language().liveSnapshot};
const taskLabels={approval_needed:['等待授权','amber'],ready:['待分发','purple'],manual_action_needed:['待人工投稿','blue'],submitted:['已提交 · 待公开','blue'],not_started:['尚未安排','neutral'],published:['已发布','green'],uncertain:['结果未知','amber'],failed:['执行失败','red'],removed:['已移除','neutral'],unconfigured:['待配置','neutral']};
const channelCatalog=[{id:'dev',name:'DEV',mode:'自动发布',summary:'开发者社区中的技术故事。使用指定账号发布全文副本，并保留原文来源。',account:'@chronoai-team',personal:'@jing-demo'},{id:'hashnode',name:'Hashnode',mode:'组织自动发布',summary:'通过组织 Pro publication 发布。连接、账号权限与精确授权需要同时有效。',account:'ChronoAI Engineering · Pro',personal:'个人 Hashnode 暂不支持'},{id:'medium',name:'Medium',mode:'辅助投稿',summary:'准备 Markdown 与来源信息，人工完成平台操作；获得公开链接后单独核验。',account:'ChronoAI · 人工操作',personal:'Jing Chen · 人工操作'},{id:'hacker',name:'HackerNoon',mode:'辅助投稿',summary:'准备稿件与来源信息，人工提交至平台编辑审核。提交与公开分别记录。',account:'ChronoAI · 公司账号',personal:'个人账号 · 核对投稿资格'}];
const routeButton=(label,route,style='',ic='')=>`<button class="btn ${style}" data-route="${route}">${ic?icon(ic):''}${label}</button>`;
const titleBlock=(eyebrow,title,copy,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div><div class="heading-actions">${action}</div></div>`;
const notice=(text,tone='')=>`<div class="calm-note ${tone}">${icon('info')}<span>${text}</span></div>`;
const emptyState=(heading,text,action='')=>`<section class="panel empty">${icon('layers')}<h3>${heading}</h3><p>${text}</p>${action}</section>`;
const isAdmin=()=>canManagePublishers();
const canManage=()=>state.workspace==='personal'||isAdmin();
function ensureSession(){if(!site.signedIn&&!['login','blog','story'].includes(state.route)){site.returnTo=state.route;state.route='login';history.replaceState(null,'','#login');}}
function resetWorkspaceContext(){site.deliveryQuery='';site.deliveryFilter='all';site.deliveryPlatform='all';site.analyticsArticle='all';site.publicQuery='';site.publicCategory='all';site.storyId='identity';state.rights=false;state.conflict=false;state.release='idle';}
function standaloneShell(content){return `<div class="standalone ${['blog','story'].includes(state.route)?'reader-shell':'entry-shell'}"><main id="main-content">${content}</main></div>${dock()}`;}
function taskStateFor(a,lang){return distributionStates.get(a.id+':'+lang);}
function isPublic(a,lang){return Boolean(a?.langs[lang]?.liveSnapshot)&&!taskStateFor(a,lang)?.originalOffline;}
function publicArticles(){return articles.filter(a=>a.owner===site.publicOwner&&isPublic(a,site.publicLang));}
function routeHash(route){if(['editor','publish','distribution'].includes(route))return `#${route}?id=${encodeURIComponent(state.articleId)}&lang=${state.lang}&owner=${state.workspace}`;if(route==='story')return `#story?id=${encodeURIComponent(site.storyId)}&lang=${site.publicLang}&owner=${site.publicOwner}`;if(route==='blog')return `#blog?lang=${site.publicLang}&owner=${site.publicOwner}`;return '#'+route+(!['login','onboarding'].includes(route)?'?owner='+state.workspace:'');}
function syncPublicRoute(){
  const [route,query='']=location.hash.slice(1).split('?'),q=new URLSearchParams(query),owner=q.get('owner');
  if(['blog','story'].includes(route)){if(owner)site.publicOwner=owner;if(['en','zh'].includes(q.get('lang')))site.publicLang=q.get('lang');if(q.get('id'))site.storyId=q.get('id');return;}
  if(accessibleWorkspace(owner)&&owner!==state.workspace){resetWorkspaceContext();state.workspace=owner;state.articleId=defaultArticle(owner);state.lang='en';state.query='';state.tab='all';state.selected.clear();}
  if(['editor','publish','distribution'].includes(route)&&q.get('id')){
    const a=articles.find(a=>a.id===q.get('id'));
    if(!a||a.owner!==state.workspace||!Object.keys(a.langs).some(k=>canReadLanguage(a,k))){state.route='content';toast('文章不存在，或当前身份无权访问。');return;}
    state.articleId=a.id;state.lang=canReadLanguage(a,q.get('lang'))?q.get('lang'):canReadLanguage(a,'en')?'en':'zh';
  }
}
const baseNavigate=navigate;
navigate=function(route){if(route==='blog'&&!['blog','story'].includes(state.route))site.publicOwner=state.workspace;baseNavigate(route);};
const baseRender=render;
render=function(){baseRender();history.replaceState(null,'',routeHash(state.route));};

function entryBrand(){return `<a class="wordmark" href="#blog" data-route="blog"><span class="brand-symbol">${mark}</span><span>ChronoAI<small>PUBLISHING STUDIO</small></span></a>`;}
function loginPage(){return `<div class="entry-layout"><section class="entry-story">${entryBrand()}<div class="entry-story-copy"><span class="eyebrow">A PLACE FOR YOUR NEXT IDEA</span><h1>好想法，<br>值得被世界<span>看见。</span></h1><p>从一段想法，到一篇文章，再到每一个对的读者。让创作和发布，成为自然连贯的一件事。</p><div class="identity-art" aria-hidden="true"><span class="art-orbit orbit-one"></span><span class="art-orbit orbit-two"></span><span class="art-center">${mark}</span><span class="art-label label-one">CREATE</span><span class="art-label label-two">CONNECT</span><span class="art-label label-three">PUBLISH</span></div></div><small class="entry-copyright">ChronoAI · An open space for connected ideas.</small></section><section class="entry-form"><div class="entry-locale">${interfaceLanguageControl()}</div><button class="entry-theme icon-btn" data-action="theme" aria-label="切换主题">${icon(state.theme==='dark'?'sun':'moon')}</button><div class="login-card"><div class="eyebrow">WELCOME TO YOUR STUDIO</div><h2>继续，把想法写下来。</h2><p>使用 NyxID 进入工作区，创作属于自己的内容，或与组织一起发布。</p><div class="identity-signin">${mark}<span>一个身份，连接创作与发布。<small>账号与组织权限由 NyxID 管理</small></span></div>${btn('使用 NyxID 登录','sign-in','primary full large','arrow')}${site.loginError?`<div class="inline-error" role="alert">${icon('info')}${esc(site.loginError)}</div>`:''}<p class="login-hint">此原型只模拟登录，不收集账号或凭证。</p><div class="entry-divider"><span>想先看看内容？</span></div>${routeButton('浏览 ChronoAI Journal','blog','full','external')}<div class="login-demo-links"><button data-action="login-cancel">演示取消登录</button><button data-action="login-fail">演示登录失败</button></div></div></section></div>`;}
function onboardingPage(){const steps=['选择工作区','确认发布站点','开始创作'];return `<div class="onboarding-wrap"><header>${entryBrand()}<div class="onboarding-header-actions">${interfaceLanguageControl()}${routeButton('稍后设置','content','quiet')}</div></header><div class="onboarding-content"><nav class="onboarding-steps" aria-label="开始使用步骤">${steps.map((s,i)=>`<span class="${site.onboardingStep===i+1?'active':site.onboardingStep>i+1?'done':''}"><b>${site.onboardingStep>i+1?'✓':i+1}</b>${s}</span>`).join('')}</nav><div class="eyebrow">MAKE ROOM FOR YOUR IDEAS</div><h1>${steps[site.onboardingStep-1]}</h1><p>${['先决定这次以谁的身份创作。内容创建后，归属将保持明确。','每个语言站点独立发布。工作区已开通的站点会显示在这里。','一切就绪，从第一篇草稿开始。'][site.onboardingStep-1]}</p><div class="onboarding-panel panel">${site.onboardingStep===1?`<button class="workspace-option ${site.chosenWorkspace==='org'?'selected':''}" data-onboard-owner="org"><span class="workspace-avatar">C</span><span><strong>ChronoAI</strong><small>组织工作区 · ${roleLabel()}<br>内容归组织所有，署名保留作者。</small></span>${icon(site.chosenWorkspace==='org'?'check':'chevron')}</button><button class="workspace-option ${site.chosenWorkspace==='personal'?'selected':''}" data-onboard-owner="personal"><span class="avatar">JC</span><span><strong>Jing 的个人空间</strong><small>个人内容 · 独立发布<br>使用自己的站点与外部连接。</small></span>${icon(site.chosenWorkspace==='personal'?'check':'chevron')}</button>`:site.onboardingStep===2?`${notice('站点需要预先开通。选择工作区不会创建 Ghost 实例或自动绑定域名。')}<div class="onboard-sites">${['en','zh'].map(l=>`<div class="site-row">${icon('globe')}<div><strong>${l==='en'?'English':'简体中文'}</strong><small>${l}.${site.chosenWorkspace==='org'?'chronoai':'jing'}.example</small></div>${badge(site.provisioning[site.chosenWorkspace]?'等待配置':'已开通',site.provisioning[site.chosenWorkspace]?'amber':'green',true)}</div>`).join('')}</div>${site.provisioning[site.chosenWorkspace]?notice('当前可以保存草稿。站点开通之前，发布入口会保持不可用。'):notice('这是一组已开通的示例站点，尚未连接真实服务。')}<button class="text-link" data-action="toggle-provision">${site.provisioning[site.chosenWorkspace]?'恢复已开通示例':'查看站点尚未开通的状态'}</button>`:`<div class="onboard-success"><span class="success-check">${icon('check')}</span><h2>欢迎来到${site.chosenWorkspace==='org'?' ChronoAI':'个人空间'}。</h2><p>从 Markdown 开始，按语言保存版本，再决定什么时候与读者见面。</p><div class="onboard-checks"><span>${icon('check')}内容归属明确</span><span>${icon('check')}中英文独立发布</span><span>${icon('check')}发布前确认版本</span></div></div>`}</div><div class="onboarding-footer">${site.onboardingStep>1?btn('上一步','onboard-back','','back'):'<span></span>'}${btn(site.onboardingStep===3?'进入工作区':'继续','onboard-next','primary','arrow')}</div></div></div>`;}

function deliveryRows(){if(!canPublish())return [];const rows=[];for(const [key,t] of distributionStates){const split=key.lastIndexOf(':'),a=articles.find(a=>a.id===key.slice(0,split)),lang=key.slice(split+1);if(!a||a.owner!==state.workspace||lang!=='en'||!a.langs[lang]?.liveSnapshot)continue;for(const channel of ['dev','medium','hashnode','hacker']){const status=t[channel];if(!status||['unconfigured','not_started'].includes(status))continue;rows.push({a,lang,channel,status,t});}}return rows;}
function deliveriesPage(){const all=deliveryRows(),needs=all.filter(r=>!['published','removed'].includes(r.status));return titleBlock('EVERY DESTINATION, ONE VIEW','发布与任务','按文章和渠道跟进，每一次发布都有清楚的结果。',routeButton('管理渠道','connections','','link'))+(!canPublish()?emptyState('创作继续，发布交给团队','组织分发任务仅对 Publisher 和 Admin 开放。自己的已提交稿件可以在内容库跟进。',routeButton('查看我的内容','content','primary')):`<div class="metric-grid three"><div class="metric-card panel"><span>需要处理</span><strong>${needs.length}<small>个渠道任务</small></strong><p>授权、人工投稿或状态核验</p></div><div class="metric-card panel"><span>已确认公开</span><strong>${all.filter(r=>r.status==='published').length}<small>个外部副本</small></strong><p>公开状态已单独核验</p></div><div class="metric-card panel"><span>待核验结果</span><strong>${all.filter(r=>r.status==='uncertain').length}<small>个结果未知任务</small></strong><p>先核验，避免重复写入</p></div></div><div class="content-toolbar"><div class="tabs">${[['all','全部任务'],['needs','需要处理'],['published','已发布']].map(([id,label])=>`<button class="tab ${site.deliveryFilter===id?'active':''}" data-delivery-filter="${id}">${label}</button>`).join('')}</div><div class="list-tools"><label class="search">${icon('search')}<input id="delivery-search" aria-label="搜索分发任务" placeholder="搜索文章" value="${esc(site.deliveryQuery)}"></label><select id="delivery-platform" class="field-select" aria-label="筛选分发平台">${[['all','全部平台'],...channelCatalog.map(c=>[c.id,c.name])].map(([id,label])=>`<option value="${id}" ${site.deliveryPlatform===id?'selected':''}>${label}</option>`).join('')}</select></div></div><div id="delivery-list">${deliveryTable()}</div>${notice('原文下线后，已知副本仍保留在任务列表。连接恢复不会自动重发内容。')}`);}
function deliveryTable(){const rows=deliveryRows().filter(r=>(site.deliveryFilter==='all'||(site.deliveryFilter==='needs'?!['published','removed'].includes(r.status):r.status===site.deliveryFilter))&&(site.deliveryPlatform==='all'||r.channel===site.deliveryPlatform)&&r.a.langs[r.lang].liveSnapshot.savedTitle.toLowerCase().includes(site.deliveryQuery.toLowerCase()));if(!rows.length)return emptyState('当前没有匹配的分发任务','原文发布后，可以在文章详情选择渠道并安排分发。',routeButton('返回内容库','content'));return `<section class="panel"><div class="delivery-table-header"><span>文章与语言</span><span>目的地</span><span>当前状态</span><span>下一步</span></div>${rows.map(r=>{const label=taskLabels[r.status]||taskLabels.ready;const failedConnection=['dev','hashnode'].includes(r.channel)&&connectionStates[state.workspace][r.channel]!=='connected';return `<div class="delivery-row"><div><strong><span data-i18n-preserve>${esc(r.a.langs[r.lang].liveSnapshot.savedTitle)}</span></strong><small>${r.lang.toUpperCase()} · ${esc(r.a.author)} · 原文 v${r.a.langs[r.lang].live}${r.t.originalOffline?' · 原文已下线':''}</small></div><div class="delivery-platform">${platform(r.channel)}<span>${channelCatalog.find(c=>c.id===r.channel).name}<small>${r.channel==='dev'?(workspaceKind(state.workspace)==='organization'?'@chronoai-team':'@jing-demo'):['medium','hacker'].includes(r.channel)?'辅助投稿':'组织 publication'}</small></span></div><div>${badge(failedConnection?'连接需恢复':label[0],failedConnection?'amber':label[1],true)}</div><button class="text-link" data-delivery-open="${r.a.id}" data-task-lang="${r.lang}">${failedConnection?'恢复连接':r.status==='uncertain'?'核验结果':r.status==='approval_needed'?'查看授权':r.status==='manual_action_needed'?'准备投稿':'查看详情'}${icon('arrow')}</button></div>`;}).join('')}</section>`;}
function analyticsPage(){const hasPublic=publicArticles().length>0||articles.some(a=>a.owner===state.workspace&&Object.keys(a.langs).some(l=>isPublic(a,l)));const pool=articles.filter(a=>a.owner===state.workspace&&Object.keys(a.langs).some(l=>isPublic(a,l)));if(site.analyticsArticle!=='all'&&!pool.some(a=>a.id===site.analyticsArticle))site.analyticsArticle='all';return titleBlock('UNDERSTAND YOUR IMPACT','数据分析','读懂内容的表现，再决定下一篇写什么。',btn('导出当前数据','export-analytics','','download'))+`<div class="analytics-filter panel"><label>时间范围<select id="analytics-period"><option value="7" ${site.analyticsPeriod==='7'?'selected':''}>最近 7 天</option><option value="30" ${site.analyticsPeriod==='30'?'selected':''}>最近 30 天</option><option value="90" ${site.analyticsPeriod==='90'?'selected':''}>最近 90 天</option></select></label><label>文章<select id="analytics-article"><option value="all">全部公开文章</option>${pool.map(a=>`<option value="${a.id}" ${site.analyticsArticle===a.id?'selected':''}>${esc((a.langs.en?.liveSnapshot||a.langs.zh.liveSnapshot).savedTitle)}</option>`).join('')}</select></label><label>语言<select id="analytics-lang">${[['all','全部语言'],['en','English'],['zh','简体中文']].map(([id,t])=>`<option value="${id}" ${site.analyticsLang===id?'selected':''}>${t}</option>`).join('')}</select></label><label>数据来源<select id="analytics-source">${[['ghost','Ghost 原文'],['dev','DEV 副本'],['medium','Medium'],['hacker','HackerNoon']].map(([id,t])=>`<option value="${id}" ${site.analyticsSource===id?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="analytics-result">${analyticsResults(hasPublic,pool)}</div>`;}
function analyticsData(){let unavailable=['medium','hacker'].includes(site.analyticsSource);const pool=articles.filter(a=>a.owner===state.workspace&&(site.analyticsArticle==='all'||a.id===site.analyticsArticle)&&Object.keys(a.langs).some(l=>(site.analyticsLang==='all'||l===site.analyticsLang)&&isPublic(a,l)));const multiplier=site.analyticsPeriod==='7'?.27:site.analyticsPeriod==='90'?2.7:1;const scope=(site.analyticsArticle==='all'?1:.32)*(site.analyticsLang==='zh'?.24:site.analyticsLang==='en'?.76:1)*(site.analyticsSource==='dev'?.43:1);const sourceAvailable=site.analyticsSource==='ghost'||site.analyticsLang!=='zh'&&pool.some(a=>taskStateFor(a,'en')?.dev==='published');if(site.analyticsSource==='dev'&&!sourceAvailable)unavailable=true;const count=pool.length&&sourceAvailable?Math.round(12840*multiplier*scope):0;return {unavailable,count,readers:Math.round(count*.72/Number(site.analyticsPeriod)),pool,multiplier,scope};}
function analyticsResults(){const d=analyticsData();const source=site.analyticsSource==='ghost'?'Ghost 原文':channelCatalog.find(c=>c.id===site.analyticsSource)?.name;return `<div class="data-source-note"><span>${icon('clock')}示例统计窗口 · 最近 ${site.analyticsPeriod} 天 · 截至 2026-11-03 14:00</span>${badge('来源：'+source,'neutral')}</div>${d.unavailable?emptyState('此来源暂不提供可用数据','Unavailable · 已发布状态与阅读指标分别记录，缺少数据不会记作 0。',btn('查看数据口径','metric-help')):`<div class="metric-grid"><section class="metric-card panel"><span>${source} 浏览次数</span><strong>${d.count.toLocaleString()}</strong><p>PV · 当前筛选范围</p></section><section class="metric-card panel"><span>日均估算读者</span><strong>${site.analyticsSource==='dev'?'—':d.readers.toLocaleString()}</strong><p>${site.analyticsSource==='dev'?'Unavailable · 渠道未提供':'每日估算 UV 的日均值'}</p></section><section class="metric-card panel"><span>公开文章</span><strong>${d.pool.length}</strong><p>仅计当前工作区与语言</p></section><section class="metric-card panel"><span>阅读时长</span><strong>—</strong><p>Unavailable · 尚未提供</p></section></div><div class="analytics-grid"><section class="panel chart-panel"><div class="section-heading"><h2>阅读趋势</h2><span><i class="legend-dot"></i> 浏览次数</span></div>${d.count?trendChart(d.count):`<div class="chart-empty">${icon('chart')}<strong>当前范围暂无阅读记录</strong><span>数据源可用，浏览次数为 0。</span></div>`}<div class="chart-caption">${site.analyticsPeriod} 天内的示例趋势 · 每日估算 UV 不等于跨日去重人数，不累加为总读者</div></section><section class="panel source-panel"><h2>阅读来源</h2><p>同一站点内的访问来源占比</p>${[['直接访问',46],['搜索引擎',28],['开发者社区',18],['其他来源',8]].map(([label,v])=>`<div class="source-bar"><div><span>${label}</span><strong>${d.count?v:0}%</strong></div><div class="bar-track"><i style="width:${d.count?v:0}%"></i></div></div>`).join('')}</section></div><section class="panel analytics-articles"><div class="section-heading"><h2>公开文章表现</h2><span>示例指标 · ${source}</span></div>${d.pool.length?d.pool.map((a,i)=>`<button class="performance-row" data-analytics-drill="${a.id}"><span>${String(i+1).padStart(2,'0')}</span><strong><span data-i18n-preserve>${esc((a.langs[site.analyticsLang]?.liveSnapshot||a.langs.en?.liveSnapshot||a.langs.zh.liveSnapshot).savedTitle)}</span></strong><span>${Math.round(d.count/(d.pool.length*(d.pool.length+1)/2)*(d.pool.length-i)).toLocaleString()} <small>浏览</small></span>${icon('chevron')}</button>`).join(''):'<p class="muted">当前筛选没有公开文章。</p>'}</section>`}${notice('不同平台的读者可能重叠，因此不显示跨平台“总独立读者”。所有数字均为演示数据。')}`;}
function trendChart(total){const values=[31,36,32,48,43,51,44,59,55,69,63,72,64,80,76];const points=values.map((v,i)=>`${40+i*43},${200-v*1.8}`).join(' ');return `<svg class="trend-chart" viewBox="0 0 680 235" role="img" aria-label="最近${site.analyticsPeriod}天浏览次数趋势，示例数据共${total}次"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8e65f5" stop-opacity=".22"/><stop offset="1" stop-color="#8e65f5" stop-opacity="0"/></linearGradient></defs>${[40,90,140,190].map((y,i)=>`<line x1="40" x2="650" y1="${y}" y2="${y}" stroke="var(--line)" stroke-dasharray="3 5"/><text x="0" y="${y+4}" fill="var(--muted)" font-size="10">${Math.round(total/(Number(site.analyticsPeriod)/15)*(4-i)/45)}</text>`).join('')}<polygon points="40,200 ${points} 642,200" fill="url(#chart-fill)"/><polyline points="${points}" fill="none" stroke="#9268f5" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="642" cy="63.2" r="5" fill="#9268f5" stroke="var(--surface)" stroke-width="3"/><text x="40" y="228" fill="var(--muted)" font-size="10">窗口开始</text><text x="312" y="228" fill="var(--muted)" font-size="10">${Math.round(Number(site.analyticsPeriod)/2)} 天前</text><text x="615" y="228" fill="var(--muted)" font-size="10">11 月 3 日</text></svg>`;}

function connectionsPage(){if(!canPublish())return titleBlock('CONNECTED, WITH INTENT','连接与渠道','使用正确的账号，让内容抵达正确的平台。')+emptyState('此区域需要发布权限','组织连接与分发仅对 Publisher 和 Admin 开放。',routeButton('返回内容库','content','primary'));return titleBlock('CONNECTED, WITH INTENT','连接与渠道','一个工作区，一组明确的发布身份。',btn('连接与权限说明','connection-help','','shield'))+`<div class="connection-banner"><div class="nyx-tile">${mark}</div><div><strong>账号由 NyxID 连接，操作由工作区权限约束。</strong><p>这里展示连接与能力；组织自动写入仍需要针对具体内容、目标和动作的批准。</p></div>${badge('NyxID 已连接','green',true)}</div><div class="connection-grid">${channelCatalog.map(c=>{const auto=['dev','hashnode'].includes(c.id),status=connectionStates[state.workspace][c.id],unsupported=status==='unsupported';const label=unsupported?'暂不支持':!auto?'人工流程':status==='connected'?'已连接':status==='expired'?'需要重连':'待配置';return `<section class="panel integration-card"><div class="channel-head">${platform(c.id)}<div class="channel-name"><strong>${c.name}</strong><small>${c.mode}</small></div>${badge(label,unsupported?'neutral':!auto?'blue':status==='connected'?'green':'amber',true)}</div><p class="integration-description">${c.summary}</p><div class="integration-account"><span>当前${workspaceKind(state.workspace)==='organization'?'组织':'个人'}账号</span><strong>${esc(workspaceKind(state.workspace)==='organization'?c.account:c.personal)}</strong></div><div class="capability-tags">${badge(auto?'确定版本写入':'生成投稿材料','neutral')}${badge(c.id==='hashnode'?'Pro publication':auto?'保留来源':'人工核验公开','neutral')}</div><div class="integration-footer"><span>${auto?(workspaceKind(state.workspace)==='organization'?'每次写入需精确授权':'使用个人授权连接'):'不会自动提交或发表'}</span><button class="btn sm ${status==='expired'?'primary':''}" data-channel="${c.id}">${unsupported?'查看范围':!auto?'查看投稿流程':status==='connected'?'查看连接':status==='expired'?'恢复连接':'配置连接'}${icon('arrow')}</button></div></section>`;}).join('')}</div><div class="capability-note panel">${icon('shield')}<div><strong>连接可用，仍需核对这一次操作。</strong><p>内容版本、发布账号、语言或动作发生变化时，旧批准不再适用。平台故障只影响对应渠道。</p></div></div>`;}
function settingsPage(){const conf=site.settings[state.workspace],editable=canManage();return titleBlock('A SPACE THAT FEELS LIKE YOURS','站点与工作区','明确工作区身份、公开站点与默认语言。',badge(editable?'可管理':'只读视图',editable?'purple':'neutral'))+`<nav class="settings-tabs">${[['general','基本信息'],['sites','发布站点']].map(([id,l])=>`<button class="${site.settingsTab===id?'active':''}" data-setting-tab="${id}">${l}</button>`).join('')}</nav><div class="settings-layout"><section class="panel settings-form">${site.settingsTab==='general'?`<div class="settings-section-title"><span class="workspace-avatar">${workspaceKind(state.workspace)==='organization'?'C':'JC'}</span><div><h2>${workspaceKind(state.workspace)==='organization'?'组织工作区':'个人工作区'}</h2><p>只改变展示信息，不改变已有文章的归属。</p></div></div><div class="form-field"><label for="workspace-name">公开站点名称</label><input id="workspace-name" maxlength="60" value="${esc(conf.name)}" ${!editable?'readonly':''}><small>展示在 Journal 页头与文章页。</small></div><div class="form-field"><label for="workspace-description">站点简介</label><textarea id="workspace-description" rows="3" maxlength="200" ${!editable?'readonly':''}>${esc(conf.description)}</textarea></div><div class="form-field"><label for="workspace-language">默认创作语言</label><select id="workspace-language" ${!editable?'disabled':''}><option value="en" ${conf.language==='en'?'selected':''}>English</option><option value="zh" ${conf.language==='zh'?'selected':''}>简体中文</option></select><small>用于新建草稿。已有文章保持当前语言。</small></div><div class="form-error" id="settings-error"></div><div class="form-footer"><span>${editable?'修改仅保存在本次原型会话中':'组织设置由 Admin 管理'}</span>${btn('保存设置','save-settings','primary','',!editable?'disabled':'')}</div>`:`<h2>语言与站点</h2><p class="section-description">一个双语 publication 对应两个独立 Ghost 站点。每个站点保留自己的文章、公开版本与地址。</p>${['en','zh'].map(l=>`<div class="site-row">${icon('globe')}<div><strong>${l==='en'?'English':'简体中文'}</strong><small>${l}.${workspaceKind(state.workspace)==='organization'?'chronoai':'jing'}.example</small></div>${badge(site.provisioning[state.workspace]?'等待配置':'已开通',site.provisioning[state.workspace]?'amber':'green')}<button class="icon-btn" data-public-site="${l}" aria-label="查看原文站点">${icon('external')}</button></div>`).join('')}${notice('域名与 Ghost 站点由部署配置管理。本页面不自动创建、迁移或删除站点。')}<div class="form-footer">${routeButton('查看公开博客','blog','','external')}</div>`}</section><aside><section class="panel aside-panel"><h2 class="aside-title">${icon('shield')}设置与权限</h2><p class="side-help">${workspaceKind(state.workspace)==='organization'?'Admin 管理组织展示信息与发布角色。Publisher 可以发布内容，但不会自动获得组织管理权限。':'个人空间中的内容、站点和连接独立于组织工作区。'}</p>${workspaceKind(state.workspace)==='organization'?routeButton('查看成员与权限','members','full quiet','arrow'):''}</section><section class="panel aside-panel"><h2 class="aside-title">${icon('globe')}公开前核对</h2><p class="side-help">站点名称与简介可以公开展示。草稿、内部任务与授权信息不会出现在博客中。</p></section></aside></div>`;}
function membersPage(){return titleBlock('THE PEOPLE BEHIND THE WORDS','成员与权限','组织权限决定可以做什么，署名记录内容由谁创作。')+(state.workspace==='personal'?emptyState('个人空间只有自己','组织成员管理位于对应组织工作区。',btn('切换工作区','workspace','primary')):`<div class="role-explainer"><div><span class="role-label">Member</span><strong>创作与提交</strong><p>编辑自己的组织草稿，提交确定版本；查看组织聚合数据。</p></div><div><span class="role-label">Publisher</span><strong>发布与分发</strong><p>发布自己或已提交的授权版本，处理分发任务。</p></div><div><span class="role-label">Admin</span><strong>组织管理</strong><p>管理工作区设置与 Publisher 权限，保留组织管理边界。</p></div></div><section class="panel member-panel"><div class="section-heading"><h2>组织成员 <span class="muted">4</span></h2>${badge(isAdmin()?'Admin 管理视图':'当前只读','neutral')}</div>${site.members.map((m,i)=>{const role=m.self?state.role:m.role;return `<div class="member-row"><span class="avatar ${i%2?'purple':''}">${m.initials}</span><div><strong>${m.name} ${m.self?'<small>当前身份</small>':''}</strong><small>${m.email}</small></div>${badge(role==='admin'?'Admin':role==='publisher'?'Publisher':'Member',role==='admin'?'purple':'neutral')}<button class="btn sm quiet" data-member="${i}" ${!isAdmin()||role==='admin'?'disabled':''}>${role==='admin'?'NyxID 管理':role==='publisher'?'撤销发布权限':'授予发布权限'}</button></div>`;}).join('')}</section>${notice('组织成员与 Admin 身份来自 NyxID。此处只演示 Publisher 权限管理，不授予成员读取他人私人草稿的权限。')}${!isAdmin()?notice('可通过底部「场景演示」切换 Admin 查看管理流程。此控件属于原型演示工具。'):''}`);}
function guidePage(){return titleBlock('FROM YOUR FIRST DRAFT, FORWARD','把好内容，送到对的地方。','从写作到分发，每一步都保留明确的身份和版本。')+(typeof setupGuideSection==='function'?setupGuideSection():'')+`<section class="guide-hero panel"><div><div class="eyebrow">YOUR FIRST PUBLISHING JOURNEY</div><h2>一篇文章，一条连贯的工作流。</h2><p>先在工作区创作，再确认原文，最后安排外部分发。中英文可以独立推进。</p>${routeButton('从内容库开始','content','primary','arrow')}${routeButton('查看首次引导','onboarding','quiet')}</div><div class="guide-path" aria-label="创作、确认、原文、分发">${[['file','创作'],['eye','确认'],['globe','原文'],['send','分发']].map(([i,t],n)=>`<span>${icon(i)}<small>0${n+1} / ${t}</small></span>`).join('')}</div></section><div class="guide-grid">${[['01','写作与双语','每个语言都有自己的草稿和线上版本。保存不会公开，译文也不会随原文自动发布。','editor'],['02','发布与身份','个人内容由本人发布；组织 Member 提交，Publisher 或 Admin 发布已授权的版本。','publish'],['03','外部分发','DEV、组织 Hashnode 自动流程需要精确授权；Medium、HackerNoon 由人完成投稿。','connections'],['04','看懂结果','已提交不代表已公开。结果未知先核验，渠道数据不可用也不会显示成零。','deliveries']].map(([n,h,p,r])=>`<button class="guide-card panel" data-route="${r}"><span class="mono">${n}</span><h3>${h}</h3><p>${p}</p><span class="text-link">查看页面 ${icon('arrow')}</span></button>`).join('')}</div><section class="panel faq"><h2>常见问题</h2>${[['保存后，读者会看到新内容吗？','不会。保存只更新草稿，完成发布确认后才会更新线上版本。'],['可以查看其他成员的草稿吗？','组织发布者只能处理自己或已提交授权的版本，成员的未提交私人草稿不会因为角色更高而自动开放。'],['原文下线，外部副本会自动消失吗？','不会。下线阻止新的分发写入，已知副本仍需要按平台逐一核验与清理。'],['这套原型会向平台发送内容吗？','不会。所有操作与身份均为本地演示；内容样例刷新恢复，开通申请保存在本机。']].map(([q,a])=>`<details><summary>${q}${icon('plus')}</summary><p>${a}</p></details>`).join('')}</section>`;}

function blogHeader(){const conf=site.settings[site.publicOwner];return `<header class="journal-header"><a class="journal-brand" href="#blog" data-route="blog">${mark}<span><span data-i18n-preserve>${esc(conf.name)}</span><small>${workspaceKind(site.publicOwner)==='organization'?'JOURNAL':'NOTES'}</small></span></a><nav aria-label="博客导航"><button data-route="blog">${site.publicLang==='en'?'Stories':'文章'}</button><button data-action="journal-about">${site.publicLang==='en'?'About':'关于'}</button></nav><div class="journal-tools"><button class="language-pill" data-public-locale="${site.publicLang==='en'?'zh':'en'}">${icon('globe')}${site.publicLang==='en'?'中文':'EN'}</button><button class="icon-btn" data-action="theme" aria-label="切换主题">${icon(state.theme==='light'?'moon':'sun')}</button><button class="btn sm" data-route="${site.signedIn?'content':'login'}">${site.signedIn?'工作台':'登录'}${icon('arrow')}</button></div></header>`;}
function blogFooter(){return `<footer class="journal-footer"><div>${mark}<span><span data-i18n-preserve>${esc(site.settings[site.publicOwner].name)}</span><small>Good ideas travel further.</small></span></div><span>© 2026 · 示例站点</span><button class="text-link" data-route="${site.signedIn?'content':'login'}">Publishing Studio ${icon('arrow')}</button></footer>`;}
function storyVisual(index=0){return `<div class="story-art art-${index%3}" aria-hidden="true"><div class="story-art-grid"></div><span class="story-art-disc"></span><span class="story-art-disc second"></span><span class="story-art-type">${['Identity.<br>Into action.','Built for<br>possibility.','Trust.<br>By design.'][index%3]}</span><span class="story-art-footer">CHRONOAI / JOURNAL — 0${index+1}</span></div>`;}
function blogPage(){const all=publicArticles(),featured=all[0];const en=site.publicLang==='en';return blogHeader()+`<div class="journal-main"><section class="journal-intro"><div><div class="eyebrow">IDEAS · PEOPLE · POSSIBILITIES</div><h1>${en?'Thoughts for a<br><span>more connected world.</span>':'连接世界的，<br><span>是一个个好想法。</span>'}</h1></div><p><span data-i18n-preserve>${esc(site.settings[site.publicOwner].description)}</span></p></section>${featured?`<button class="featured-story" data-story="${featured.id}">${storyVisual(0)}<div class="featured-copy"><span class="eyebrow">${en?'FEATURED STORY':'精选文章'}</span><div class="story-category">${esc(featured.category)} · ${en?'3 MIN READ':'3 分钟阅读'}</div><h2><span data-i18n-preserve>${esc(featured.langs[site.publicLang].liveSnapshot.savedTitle)}</span></h2><p><span data-i18n-preserve>${esc(featured.langs[site.publicLang].liveSnapshot.savedBody.split('\n')[0])}</span></p><div class="story-byline"><span class="avatar">${featured.initials}</span><span>${featured.author}<small>Nov 3, 2026</small></span><span class="read-arrow">${icon('arrow')}</span></div></div></button>`:''}<section class="journal-latest"><div class="journal-section-head"><h2>${en?'The latest thinking':'最近的想法'}</h2><label class="search">${icon('search')}<input id="public-search" type="search" aria-label="搜索公开文章" placeholder="${en?'Search stories':'搜索文章'}" value="${esc(site.publicQuery)}"></label></div><div class="journal-categories">${['all',...new Set(all.map(a=>a.category))].map(c=>`<button data-public-category="${c}" class="${site.publicCategory===c?'active':''}">${c==='all'?(en?'All stories':'全部文章'):c}</button>`).join('')}</div><div id="public-list">${blogCards()}</div></section><section class="journal-manifesto"><span class="eyebrow">INDEPENDENT IDEAS. SHARED POSSIBILITIES.</span><h2>${en?'Better work starts<br>with a new perspective.':'每一次更好的工作，<br>都始于一个新的视角。'}</h2><p>${en?'Notes from the people building what comes next.':'记录构建过程，分享真实思考。'}</p>${routeButton(en?'Explore the studio':'走进创作工作台',site.signedIn?'content':'login','','arrow')}</section></div>`+blogFooter();}
function blogCards(){const list=publicArticles().filter(a=>(site.publicCategory==='all'||a.category===site.publicCategory)&&a.langs[site.publicLang].liveSnapshot.savedTitle.toLowerCase().includes(site.publicQuery.toLowerCase()));return list.length?`<div class="story-card-grid">${list.map((a,i)=>`<button class="story-card" data-story="${a.id}">${storyVisual(i+1)}<div class="story-category">${a.category} · ${site.publicLang==='en'?'3 MIN READ':'3 分钟阅读'}</div><h3><span data-i18n-preserve>${esc(a.langs[site.publicLang].liveSnapshot.savedTitle)}</span></h3><p><span data-i18n-preserve>${esc(a.langs[site.publicLang].liveSnapshot.savedBody.split('\n')[0])}</span></p><div class="story-card-byline">${a.author}<span>Nov 3, 2026</span></div></button>`).join('')}</div>`:emptyState(site.publicLang==='en'?'No stories found':'还没有匹配的公开文章',site.publicLang==='en'?'Try another search or language.':'可以调整关键词、分类或语言。',btn('清除搜索与分类','reset-public'));}
function storyPage(){const a=articles.find(a=>a.id===site.storyId&&a.owner===site.publicOwner),en=site.publicLang==='en';if(!a||!isPublic(a,site.publicLang))return blogHeader()+`<div class="reader-not-found">${emptyState(en?'This story isn’t available':'这篇文章暂不可见',en?'It may be unpublished, or this language is not available.':'可能尚未发布、已经下线，或当前语言版本不可用。',routeButton(en?'Back to stories':'返回文章列表','blog','primary'))}</div>`+blogFooter();const l=a.langs[site.publicLang].liveSnapshot,other=en?'zh':'en';let headingIndex=0;const body=renderMarkdown(l.savedBody,{article:a,lang:site.publicLang,public:true,version:l.version}).replace(/<h2>/g,()=>`<h2 id="section-${headingIndex++}">`);const headings=l.savedBody.split('\n').filter(p=>p.startsWith('## '));return blogHeader()+`<article class="journal-article"><button class="back-link" data-route="blog">${icon('back')}${en?'All stories':'全部文章'}</button><header class="story-heading"><div class="eyebrow">${a.category} / ${en?'ENGLISH':'简体中文'}</div><h1><span data-i18n-preserve>${esc(l.savedTitle)}</span></h1><div class="story-meta"><span class="avatar ${a.color}">${a.initials}</span><span>${a.author}<small>Nov 3, 2026 · 3 min read</small></span>${isPublic(a,other)?`<button class="language-pill" data-story-locale="${other}">${icon('globe')}${en?'阅读中文版':'Read in English'}</button>`:''}</div></header>${storyVisual(0)}<div class="reading-grid"><aside class="reading-toc"><span class="eyebrow">${en?'ON THIS PAGE':'文章目录'}</span>${headings.map((h,i)=>`<a href="#section-${i}" data-section="section-${i}">${esc(h.slice(3))}</a>`).join('')}<button class="text-link" data-action="copy-story">${icon('link')}${en?'Share this story':'分享文章'}</button></aside><div class="reading-body">${body}<div class="author-bio"><span class="avatar ${a.color}">${a.initials}</span><div><strong>${a.author}</strong><p>${en?'Building useful things. Writing about identity, agents, and the way we work.':'构建有用的产品，记录身份、Agent 与工作方式的变化。'}</p></div></div></div></div><div class="related-stories"><div class="journal-section-head"><h2>${en?'Keep exploring':'继续阅读'}</h2>${routeButton(en?'All stories':'全部文章','blog','quiet','arrow')}</div><div class="related-grid">${publicArticles().filter(x=>x.id!==a.id).slice(0,2).map(x=>`<button data-story="${x.id}"><span class="eyebrow">${x.category}</span><h3><span data-i18n-preserve>${esc(x.langs[site.publicLang].liveSnapshot.savedTitle)}</span></h3><span class="text-link">${x.author}${icon('arrow')}</span></button>`).join('')||`<p class="muted">${en?'More stories are on the way.':'更多文章正在创作中。'}</p>`}</div></div></article>`+blogFooter();}

Object.assign(pageRenderers,{login:loginPage,onboarding:onboardingPage,deliveries:deliveriesPage,analytics:analyticsPage,connections:connectionsPage,settings:settingsPage,members:membersPage,guide:guidePage,blog:blogPage,story:storyPage});

// Actions mutate only the current browser session. Authorization is checked at action time.
Object.assign(actions,{
  'sign-in'(){site.signedIn=true;site.loginError='';site.onboardingStep=1;state.route='onboarding';render();},
  'login-cancel'(){site.loginError='登录已取消。可以重新登录，或继续浏览公开内容。';render();},
  'login-fail'(){site.loginError='暂时无法连接 NyxID。请重试，已有内容不会受到影响。';render();},
  'onboard-back'(){site.onboardingStep=Math.max(1,site.onboardingStep-1);render();},
  'onboard-next'(){if(site.onboardingStep<3){site.onboardingStep++;render();return;}resetWorkspaceContext();state.workspace=site.chosenWorkspace;state.articleId=defaultArticle(state.workspace);state.lang='en';state.route='content';state.query='';state.tab='all';state.selected.clear();render();},
  'toggle-provision'(){site.provisioning[site.chosenWorkspace]=!site.provisioning[site.chosenWorkspace];render();},
  'account-menu'(){modal('Jing Chen',`<div class="account-card"><span class="avatar">JC</span><div><strong>Jing Chen</strong><small>jing@chronoai.example</small></div>${badge('NyxID','purple')}</div><p>当前工作区：${esc(ownerName())} · ${roleLabel()}</p><button class="choice" data-action="workspace">${icon('building')}切换工作区${icon('chevron')}</button><button class="choice" data-modal-route="onboarding">${icon('help')}重新体验首次引导${icon('chevron')}</button>`,btn('关闭','close-modal')+btn('退出演示账号','sign-out','danger'));},
  'sign-out'(){closeModal();guard(()=>{state.rights=false;state.release='idle';site.signedIn=false;site.loginError='';state.route='login';render();});},
  'mobile-nav'(){modal('工作区导航',`<button class="choice selected" data-action="workspace"><span class="workspace-avatar">${workspaceKind(state.workspace)==='organization'?'C':'JC'}</span><span><strong>${esc(ownerName())}</strong><small>${roleLabel()} · 切换工作区</small></span>${icon('down')}</button><nav class="mobile-nav-list">${[['content','内容库','layers'],['deliveries','发布与任务','send'],['analytics','数据分析','chart'],['connections','连接与渠道','link'],['settings','站点与工作区','settings'],...(workspaceKind(state.workspace)==='organization'?[['members','成员与权限','user']]:[]),['guide','开始使用','help'],['blog','公开博客','globe']].map(([r,l,i])=>`<button data-modal-route="${r}">${icon(i)}${l}${icon('chevron')}</button>`).join('')}<button data-action="mobile-import">${icon('upload')}导入 Markdown${icon('chevron')}</button></nav>`);},
  sitemap(){const groups=[['进入与引导',['login','onboarding']],['创作与发布',['content','editor','publish','distribution','deliveries']],['管理与洞察',['analytics','connections','settings','members','guide']],['公开阅读',['blog','story']]];modal('全站原型 · 页面地图',`<p class="prototype-explainer">14 个页面 · 所有数据、账号与结果均为示例。登录后的默认身份为 Publisher，角色可在场景演示中切换。</p><div class="sitemap-grid">${groups.map(([title,routes])=>`<section><h3>${title}</h3>${routes.map(r=>`<button data-modal-route="${r}">${routeTitles[r]}${icon('arrow')}</button>`).join('')}</section>`).join('')}</div>`,btn('关闭','close-modal'),true);},
  notifications(){const needs=deliveryRows().filter(r=>!['published','removed'].includes(r.status));modal('需要处理的事项',needs.length?`<p>仅展示当前工作区有权处理的任务。</p>${needs.map(r=>`<button class="notification-row" data-delivery-open="${r.a.id}" data-task-lang="${r.lang}">${platform(r.channel)}<span><strong>${channelCatalog.find(c=>c.id===r.channel).name} · ${taskLabels[r.status][0]}</strong><small><span data-i18n-preserve>${esc(r.a.langs[r.lang].liveSnapshot.savedTitle)}</span></small></span>${icon('chevron')}</button>`).join('')}`:'<p>当前没有待处理的分发任务，可以继续创作自己的内容。</p>',btn('关闭','close-modal')+`<button class="btn primary" data-modal-route="deliveries">查看全部任务</button>`);},
  'analytics-info'(){navigate('analytics');},
  'article-analytics'(){site.analyticsArticle=isPublic(current(),state.lang)?current().id:'all';site.analyticsLang=state.lang;navigate('analytics');},
  'settings-info'(){navigate('settings');},
  connections(){navigate('connections');},
  guide(){navigate('guide');},
  'metric-help'(){modal('数据口径',`<p><strong>浏览次数（PV）</strong>记录当前来源的访问；<strong>每日估算 UV</strong>只用于观察单日变化；卡片展示所选日期内的日均值。</p><p>原型数字为示例，不代表真实流量。Unavailable 表示无法取得数据；0 表示来源可用但没有记录。私人预览不计数。</p><p>不同平台的用户身份不能直接合并，不将每日估算 UV 累加成整段时间的去重人数。</p>`,btn('明白了','close-modal','primary'));},
  'export-analytics'(){const d=analyticsData();download('chronoai-analytics-demo.csv',`scope,source,period,article,language,views,daily_estimated_uv_average\n${state.workspace},${site.analyticsSource},${site.analyticsPeriod},${site.analyticsArticle},${site.analyticsLang},${d.unavailable?'Unavailable':d.count},${d.unavailable||site.analyticsSource!=='ghost'?'Unavailable':d.readers}\n`);toast('已导出当前筛选下的示例数据。');},
  'connection-help'(){modal('连接不等于发布许可',`<p>NyxID 管理账号连接，CMS 记录工作区和文章权限。组织自动写入需要对具体的版本、账号、语言和动作取得精确批准。</p><p>恢复连接不会换用其他账号，也不会自动重发结果未知的任务。此原型不接收 API Key 或凭证。</p>`,btn('明白了','close-modal','primary'));},
  'connect-channel'(){if(!canPublish()||!site.channel)return;const id=site.channel;if(state.workspace==='personal'&&id==='hashnode')return;connectionStates[state.workspace][id]='connected';closeModal();render();toast('演示：指定账号连接已恢复，现有任务结果保持不变。');},
  'expire-channel'(){if(!canPublish()||!site.channel)return;connectionStates[state.workspace][site.channel]='expired';closeModal();render();toast('演示：此工作区使用该连接的文章均需要重连。');},
  'save-settings'(){if(!canManage())return;const name=document.getElementById('workspace-name').value.trim(),description=document.getElementById('workspace-description').value.trim();if(!name){document.getElementById('settings-error').textContent='请填写公开站点名称。';return;}site.settings[state.workspace]={name,description,language:document.getElementById('workspace-language').value};render();toast('工作区展示信息已保存到本次演示。');},
  'confirm-role'(){if(!isAdmin()||!site.roleTarget)return;const {index,role}=site.roleTarget,m=site.members[index];if(!m||m.role==='admin'||m.self)return;m.role=role;site.roleTarget=null;closeModal();render();toast(`已模拟${role==='publisher'?'授予':'撤销'} ${m.name} 的发布权限。`);},
  'journal-about'(){modal('<span data-i18n-preserve>'+esc(site.settings[site.publicOwner].name)+'</span>',`<p><span data-i18n-preserve>${esc(site.settings[site.publicOwner].description)}</span></p><p>记录身份、Agent 与工作方式的变化，分享构建过程中的想法。</p>`,btn('继续阅读','close-modal','primary'));},
  'reset-public'(){site.publicCategory='all';site.publicQuery='';render();},
  'copy-story'(){modal('分享公开文章',`<p>这是本机可预览的文章链接。公开评审时需使用部署后的地址。</p><label class="form-field">原型文章链接<input readonly value="${esc(location.origin+location.pathname+routeHash('story'))}" aria-label="原型文章链接"></label>`,btn('关闭','close-modal'));},
  translations(){const a=current();modal('两种语言，各自发布',`<p>两篇关联稿件，对应两个独立原文站点。切换标签只切换当前稿件；保存、发布与下线分别生效。</p>${['en','zh'].map(k=>`<div class="history-item"><div><strong>${k==='en'?'English':'简体中文'}</strong><small class="mono">${publicationTarget(a.owner,k).displayAddress}</small><small>${canReadLanguage(a,k)?`可见版本 v${readableLanguage(a,k).version} · 线上 ${isPublic(a,k)?'v'+a.langs[k].live:'未公开'}`:'尚未创建'}</small></div>${badge(a.langs[k]?.stale?'需要核对':'独立版本',a.langs[k]?.stale?'amber':'neutral')}</div>`).join('')}${a.langs.zh?.stale?'<p>确认译文已对应当前英文草稿后，可以记录已核对。此动作不会自动保存或发布译文。</p>':''}`,btn('关闭','close-modal')+(a.langs.zh?.stale&&canEdit()?btn('标记译文已核对','translation-reviewed','primary','',dirty()?'disabled':''):''));},
  'translation-reviewed'(){if(!canEdit()||dirty()||!current().langs.zh)return;current().langs.zh.stale=false;closeModal();render();toast('译文已记录核对，仍需单独确认发布。');},
  'offline-original'(){if(!canPublish()||!isPublic(current(),state.lang))return;modal('下线当前语言的原文',`<p>将下线 <strong><span data-i18n-preserve>${esc(language().liveSnapshot.savedTitle)}</span></strong> 的 ${state.lang==='en'?'English':'简体中文'} 版本。另一个语言版本保持原状。</p><p>已知外部副本不会自动消失，仍可在分发详情逐项核验或移除。</p>`,btn('取消','close-modal')+btn('确认下线 · 演示','confirm-offline','danger'));},
  'confirm-offline'(){if(!canPublish()||!language().liveSnapshot)return;state.originalOffline=true;if(!Object.keys(current().langs).some(l=>isPublic(current(),l)))current().status='offline';recordEvent('当前语言原文已核验下线');closeModal();render();toast('演示：原文已下线，其他语言与外部副本保持原状。');},
  'restore-original'(){if(!canPublish())return;closeModal();navigate('publish');},
  'request-channel'(){const id=site.channel;if(!['hashnode','hacker'].includes(id)||!canPublish()||!language().liveSnapshot||state.lang!=='en')return;const t=distributionState();if(state.originalOffline){toast('原文下线后暂停新的分发。');return;}if(id==='hashnode'&&(state.workspace!=='org'||connectionStates.org.hashnode!=='connected')){showChannel('hashnode');return;}t[id+'Snapshot']={...language().liveSnapshot};t[id]=id==='hashnode'?'approval_needed':'manual_action_needed';render();},
  'extra-approve'(){if(!canPublish()||state.originalOffline||state.lang!=='en'||state.workspace!=='org'||connectionStates.org.hashnode!=='connected')return;const t=distributionState();if(t.hashnodeSnapshot?.version!==language().live){toast('原文版本已变化，请重新确认分发版本。');return;}modal('Hashnode · 精确授权请求',`<p>内容：<span data-i18n-preserve>${esc(t.hashnodeSnapshot.savedTitle)}</span> · English · v${t.hashnodeSnapshot.version}</p><div class="review-line"><span>目标</span><span>ChronoAI Engineering · Pro</span></div><div class="review-line"><span>动作</span><span>新建全文副本</span></div><p class="prototype-explainer">演示 NyxID Admin 对该内容、账号和动作批准的回执。</p>`,btn('关闭','close-modal')+btn('模拟 Admin 批准回执','extra-approve-done','primary'));},
  'extra-approve-done'(){const t=distributionState();if(!canPublish()||state.originalOffline||state.workspace!=='org'||connectionStates.org.hashnode!=='connected'||t.hashnodeSnapshot?.version!==language().live)return;t.hashnode='published';recordEvent('Hashnode 组织副本已核验公开');closeModal();render();},
  'extra-package'(){if(!canPublish()||!language().liveSnapshot)return;site.channel='hacker';const t=distributionState();if(['not_started','manual_action_needed'].includes(t.hacker)&&!state.originalOffline){t.hackerSnapshot={...language().liveSnapshot};t.hacker='manual_action_needed';}if(!t.hackerSnapshot)return;modal('HackerNoon 投稿材料',`<p>使用适合原文来源的账号在平台完成投稿，并跟进编辑审核。</p><div class="package-preview"><span data-i18n-preserve>${esc(t.hackerSnapshot.savedTitle)}</span>\n\nAuthor: ${esc(current().author)}\nOriginal: ${esc(sourceUrl())}\n\n<span data-i18n-preserve>${esc(t.hackerSnapshot.savedBody.slice(0,300))}</span>…</div>`,btn('关闭','close-modal')+btn('下载材料','extra-download','primary'));},
  'extra-download'(){const t=distributionState();if(!canPublish()||!t.hackerSnapshot)return;download('hackernoon-submission.md',`# ${t.hackerSnapshot.savedTitle}\n\nAuthor: ${current().author}\nOriginal: ${sourceUrl()}\n\n${t.hackerSnapshot.savedBody}`);toast('已下载示例稿件，仍需人工投稿。');},
  'extra-submit'(){const t=distributionState();if(!canPublish()||state.originalOffline||!language().liveSnapshot)return;if(t.hackerSnapshot?.version!==language().live){toast('原文已更新，请先获取当前版本的投稿材料。');return;}modal('记录 HackerNoon 投稿',`<p>确认已使用当前版本 v${t.hackerSnapshot.version} 完成人工投稿。此记录不代表平台已公开文章。</p>`,btn('取消','close-modal')+btn('记录为已提交','extra-submitted','primary'));},
  'extra-submitted'(){if(!canPublish()||state.originalOffline)return;distributionState().hacker='submitted';recordEvent('HackerNoon 已提交，待编辑审核');closeModal();render();},
  'extra-verify'(){if(!canPublish())return;modal('核验 HackerNoon 公开结果',`<p>生产流程需要核对真实公开文章与原文来源。这里仅模拟平台编辑审核完成后的结果。</p>`,btn('关闭','close-modal')+btn('模拟公开核验通过','extra-verified','primary'));},
  'extra-verified'(){if(!canPublish())return;distributionState().hacker='published';recordEvent('HackerNoon 公开结果已核验');closeModal();render();},
  'extra-preview'(){showPreview('HackerNoon 副本阅读效果',distributionState().hackerSnapshot);},
  'hashnode-preview'(){showPreview('Hashnode 副本阅读效果',distributionState().hashnodeSnapshot);},
  'retry-dev'(){if(!canPublish()||state.originalOffline||state.connectionLost)return;state.dev=current().owner==='personal'?'ready':'approval_needed';state.devSnapshot={...language().liveSnapshot};recordEvent(workspaceKind(state.workspace)==='organization'?'明确失败后重新确认版本，需新的精确授权':'明确失败后，重新确认个人分发版本');render();},
  'demo-failure'(){closeModal();state.dev='failed';state.route='distribution';render();}
});
function showChannel(id){const c=channelCatalog.find(c=>c.id===id);if(!c||!canPublish())return;site.channel=id;const auto=['dev','hashnode'].includes(id),status=connectionStates[state.workspace][id],account=workspaceKind(state.workspace)==='organization'?c.account:c.personal;modal(c.name+' · '+c.mode,`<p>${c.summary}</p><div class="review-line"><span>工作区</span><span>${esc(ownerName())}</span></div><div class="review-line"><span>指定账号</span><span>${account}</span></div>${id==='hashnode'?'<p>需要组织 Pro publication 和正确的发布账号权限；个人 Hashnode 不在当前范围内。</p>':''}${auto?'<p class="prototype-explainer">下方按钮仅模拟 NyxID 返回的连接状态，不建立真实连接，也不会发起发布。</p>':'<ol class="workflow-steps"><li>在文章分发详情获取当前公开版本材料。</li><li>到平台完成人工投稿，记录已提交。</li><li>获得公开结果后，再核验发布状态。</li></ol>'}`,btn('关闭','close-modal')+(auto&&status!=='unsupported'?(status==='connected'?btn('演示连接失效','expire-channel','quiet'):btn(status==='expired'?'模拟原账号已重连':'模拟指定账号已配置','connect-channel','primary')):''));}
function extraChannels(){const t=distributionState(),h=t.hashnode||'unconfigured',n=t.hacker||'not_started',hEnabled=workspaceKind(state.workspace)==='organization';const hOld=t.hashnodeSnapshot&&t.hashnodeSnapshot.version!==language().live;return `<section class="panel channel-card"><div class="channel-head">${platform('hashnode')}<div class="channel-name"><strong>Hashnode</strong><small>组织 Pro publication · 自动发布</small></div>${badge(!hEnabled?'范围外':connectionStates.org.hashnode!=='connected'?'待配置连接':hOld&&h!=='published'?'版本待确认':taskLabels[h]?.[0]||'待安排',h==='published'?'green':'neutral')}</div><div class="channel-message"><strong>${h==='published'?'副本已确认公开':!hEnabled?'个人 Hashnode 暂不支持':'为组织开发者内容安排分发'}</strong><p>${h==='published'?`已确认版本 v${t.hashnodeSnapshot?.version}；原文后续更新不会静默改变此副本。`:'先确认 Pro publication 和指定账号，再申请具体内容与动作的授权。'}</p></div><div class="channel-actions"><button class="text-link" data-channel="hashnode">${icon('link')}查看连接</button>${h==='published'?btn('查看副本','hashnode-preview','sm','external'):connectionStates.org.hashnode!=='connected'||!hEnabled?'<button class="btn sm" data-channel="hashnode">查看前置条件</button>':h==='approval_needed'&&!hOld?btn('查看精确授权','extra-approve','sm','',state.originalOffline?'disabled':''):`<button class="btn sm" data-start-channel="hashnode" ${state.originalOffline?'disabled':''}>确认分发版本</button>`}</div></section><section class="panel channel-card"><div class="channel-head">${platform('hacker')}<div class="channel-name"><strong>HackerNoon</strong><small>辅助投稿 · 平台编辑审核</small></div>${badge(taskLabels[n]?.[0]||'待人工投稿',n==='published'?'green':'blue')}</div><div class="channel-message blue"><strong>${n==='published'?'已核验公开':n==='submitted'?'等待平台编辑审核':'材料准备好后，由人完成投稿'}</strong><p>记录提交后，获得公开结果并核验，才标记为已发布。原文需要保留来源。</p></div><div class="channel-actions"><button class="text-link" data-action="extra-package">${icon('download')}获取投稿材料</button>${n==='published'?btn('查看副本','extra-preview','sm','external'):n==='submitted'?btn('核验公开结果','extra-verify','sm'):n==='not_started'?btn('准备投稿材料','extra-package','sm','',state.originalOffline?'disabled':''):btn('记录投稿结果','extra-submit','sm','',state.originalOffline?'disabled':'')}</div></section>`;}
const basicDistribution=pageRenderers.distribution;
pageRenderers.distribution=()=>{let html=basicDistribution();if(canPublish()&&language().live&&state.lang==='en'){html=html.replace(/<section class="panel channel-card compact">[\s\S]*?<\/section><section class="panel channel-card compact">[\s\S]*?<\/section>/,extraChannels());html=html.replace('2 个已配置','按渠道独立跟进');}return html.replace('<div class="editor-top">','<div class="distribution-return">'+routeButton('全部分发任务','deliveries','quiet','back')+'</div><div class="editor-top">')+`<div class="original-management panel"><div><strong>原文管理 · ${state.lang==='en'?'English':'简体中文'}</strong><p>${state.originalOffline?'原文已下线，可重新确认发布。':'下线当前语言原文，不自动删除其他语言或外部副本。'}</p></div>${state.originalOffline?btn('重新确认发布','restore-original','','',!canPublish()?'disabled':''):btn('下线原文','offline-original','danger','',!canPublish()||!language().live?'disabled':'')}</div>`;};
const basicDevCard=devCard;
devCard=function(){if(state.dev!=='failed'||state.connectionLost)return basicDevCard();return `<section class="panel channel-card"><div class="channel-head">${platform('dev')}<div class="channel-name"><strong>DEV</strong><small>自动发布 · ${workspaceKind(state.workspace)==='organization'?'@chronoai-team':'@jing-demo'}</small></div>${badge('执行失败','red',true)}</div><div class="channel-message"><strong>平台明确返回失败，未创建副本。</strong><p>可以确认当前版本后重试；如果结果未知，应先核验。</p></div>${btn('重新确认任务','retry-dev','sm','refresh',!canPublish()||state.originalOffline?'disabled':'')}</section>`;};
const basicDemo=actions.demo;
