const basicConfirmProblem=confirmationProblem;
confirmationProblem=function(){return site.provisioning[state.workspace]&&canPublish()?'当前工作区站点尚未开通。可以保存草稿，待站点配置后发布。':basicConfirmProblem();};
const basicNew=actions.new;
actions.new=()=>{guard(()=>{const lang=site.settings[state.workspace].language,id='draft-'+Date.now();articles.unshift({id,owner:state.workspace,creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'未分类',updated:'刚刚',status:'draft',langs:{[lang]:langData(lang==='en'?'Untitled story':'未命名文章','',1)}});state.articleId=id;state.lang=lang;state.route='editor';state.conflict=false;state.editorView='markdown';state.rights=false;render();});};
const basicPublishPage=pageRenderers.publish;
pageRenderers.publish=()=> (site.provisioning[state.workspace]?notice('当前工作区站点尚未开通，发布暂不可用。请在工作区设置中查看站点信息。'):'')+basicPublishPage();
const basicReconnect=actions.reconnect;
