// Delegated handlers keep the freshly rendered DOM independent of stored demo data.
document.addEventListener('click',event=>{
  const el=event.target.closest('button,a');if(!el||el.disabled)return;
  if(el.dataset.modalRoute){closeModal();if(el.dataset.modalRoute==='onboarding')site.onboardingStep=1;navigate(el.dataset.modalRoute);return;}
  if(el.dataset.onboardOwner){site.chosenWorkspace=el.dataset.onboardOwner;render();return;}
  if(el.dataset.deliveryFilter){site.deliveryFilter=el.dataset.deliveryFilter;render();return;}
  if(el.dataset.deliveryOpen){closeModal();openArticle(el.dataset.deliveryOpen,'distribution');state.lang=el.dataset.taskLang||'en';render();return;}
  if(el.dataset.analyticsDrill){site.analyticsArticle=el.dataset.analyticsDrill;render();return;}
  if(el.dataset.settingTab){site.settingsTab=el.dataset.settingTab;render();return;}
  if(el.dataset.channel){showChannel(el.dataset.channel);return;}
  if(el.dataset.startChannel){site.channel=el.dataset.startChannel;actions['request-channel']();return;}
  if(el.dataset.member!==undefined){if(!isAdmin())return;const index=Number(el.dataset.member),m=site.members[index];if(!m||m.role==='admin'||m.self)return;const role=m.role==='publisher'?'member':'publisher';site.roleTarget={index,role};modal(role==='publisher'?'授予发布权限':'撤销发布权限',`<p><span data-i18n-preserve>${esc(m.name)}</span> 将${role==='publisher'?'能够发布自己或已提交的授权版本，并处理组织分发':'回到 Member 权限，仍可编辑和提交自己的组织草稿'}。</p><p>已有文章归属和署名不会改变；这不会赋予读取其他成员未提交草稿的权限。</p>`,btn('取消','close-modal')+btn('确认变更 · 演示','confirm-role',role==='publisher'?'primary':'danger'));return;}
  if(el.dataset.publicSite){site.publicOwner=state.workspace;site.publicLang=el.dataset.publicSite;site.publicCategory='all';site.publicQuery='';navigate('blog');return;}
  if(el.dataset.publicCategory){site.publicCategory=el.dataset.publicCategory;render();return;}
  if(el.dataset.publicLocale){site.publicLang=el.dataset.publicLocale;site.publicCategory='all';site.publicQuery='';state.route='blog';render();window.scrollTo(0,0);return;}
  if(el.dataset.storyLocale){const a=articles.find(a=>a.id===site.storyId);if(!isPublic(a,el.dataset.storyLocale))return;site.publicLang=el.dataset.storyLocale;render();window.scrollTo(0,0);return;}
  if(el.dataset.story){site.storyId=el.dataset.story;navigate('story');if(state.route==='story'){render();window.scrollTo(0,0);}return;}
  if(el.dataset.section){event.preventDefault();document.getElementById(el.dataset.section)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='delivery-search'){site.deliveryQuery=el.value;document.getElementById('delivery-list').innerHTML=deliveryTable();}if(el.id==='public-search'){site.publicQuery=el.value;document.getElementById('public-list').innerHTML=blogCards();}});
document.addEventListener('change',event=>{const el=event.target;const fields={'analytics-period':'analyticsPeriod','analytics-article':'analyticsArticle','analytics-lang':'analyticsLang','analytics-source':'analyticsSource','delivery-platform':'deliveryPlatform'};if(fields[el.id]){site[fields[el.id]]=el.value;render();}});
function articleTaskCounts(){const tasks=['dev','medium','hashnode','hacker'].map(c=>distributionState()[c]).filter(s=>s&&!['not_started','unconfigured'].includes(s));return {pending:tasks.filter(s=>!['published','removed'].includes(s)).length,published:tasks.filter(s=>s==='published').length};}
function handleLocationChange(){const nextHash=location.hash,next=nextHash.slice(1).split('?')[0];if(!routeNames.includes(next))return;const apply=()=>{state.release='idle';state.rights=false;history.replaceState(null,'',nextHash);state.route=next;syncPublicRoute();render();window.scrollTo(0,0);};if(state.route==='editor'&&dirty()){history.replaceState(null,'',routeHash(state.route));guard(apply);}else apply();}
actions['mobile-import']=()=>{closeModal();actions.import();};
const establishedDevCard=devCard;
